import{_ as t,o as e,c as r,a2 as s}from"./chunks/framework.DuPBmefI.js";const h=JSON.parse('{"title":"协恩中学 · 2020-21年度 · 中一 · 面试","description":"","frontmatter":{"schema":"exam-report-v3","generated_from":"assets/exam-feedback","school_slug":"school-fd1436e9","school_zh":"协恩中学","school_en":"—","grade":"s1","year":"2020-21","year_label":"2020-21年度","type":"interview","title":"协恩中学 · 2020-21年度 · 中一 · 面试","anonymous":true,"source_ids":["C1821-HYS-2021-FIRST","C1821-HYS-2021-SECOND"],"rounds":["r1","r2"]},"headers":[],"relativePath":"reports/school-fd1436e9/s1/2020-21-interview.md","filePath":"reports/school-fd1436e9/s1/2020-21-interview.md"}'),n={name:"reports/school-fd1436e9/s1/2020-21-interview.md"};function p(a,o,c,l,i,g){return e(),r("div",null,[...o[0]||(o[0]=[s('<h1 id="协恩中学-·-2020-21年度-·-中一-·-面试" tabindex="-1">协恩中学 · 2020-21年度 · 中一 · 面试 <a class="header-anchor" href="#协恩中学-·-2020-21年度-·-中一-·-面试" aria-label="Permalink to &quot;协恩中学 · 2020-21年度 · 中一 · 面试&quot;">​</a></h1><p><a href="/hk-exam-web/schools/school-fd1436e9">← 返回协恩中学资料库</a></p><blockquote><p>以下内容根据考试及面试资料整理，已作匿名化与书面化处理，非逐字实录。具体安排请以当次考试通知为准。</p></blockquote><h2 id="record-c1821-hys-2021-first" tabindex="-1">资料来源：【其它机构】升中面试经验汇总_18-21.pdf <a class="header-anchor" href="#record-c1821-hys-2021-first" aria-label="Permalink to &quot;资料来源：【其它机构】升中面试经验汇总_18-21.pdf {#record-c1821-hys-2021-first}&quot;">​</a></h2><p><strong>资料类型：</strong> 不同学生的历史面试反馈汇编</p><p><strong>入学途径：</strong> 中一入学</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="第一轮-·-原文明示" tabindex="-1">第一轮 · 原文明示 <a class="header-anchor" href="#第一轮-·-原文明示" aria-label="Permalink to &quot;第一轮 · 原文明示&quot;">​</a></h3><blockquote><p><strong>考核安排：</strong></p><p><strong>网上短讲与时间差异</strong></p><p>网上面试，部分使用Google Meet。一组约4至5分钟，先用1分钟准备两题，再分别用1分钟回答中文及英文题；另有考生记为两题合共3分钟。</p></blockquote><blockquote><p><strong>语文：</strong> 粤语</p><p><strong>个人成长与家庭教育</strong></p><p>想改善自己哪一个缺点？家长应否用金钱鼓励孩子读书？孩子没有礼貌是否属父母责任？是否认同香港孩子太辛苦，或不够独立、过于依赖别人？</p><p><strong>社会观点与学校参与</strong></p><p>世界上最重要的发明是什么？应否让学生参与制定校规，为什么？是否同意“科技越进步，人类就越退步”？</p></blockquote><blockquote><p><strong>英语：</strong> 英语</p><p><strong>一分钟即席话题</strong></p><p>不同考生的题目包括Competition、The day I went hiking、What is the best thing in your life、Team spirit、Rainy days、Secret、The Online World，以及An Unforgettable Holiday。</p></blockquote><blockquote><p><strong>个人面谈：</strong> 中文、英语</p><p><strong>体育专长与语言适应</strong></p><p>另有英语自我介绍及如何平衡学习与乒乓球；中文追问同龄排名之前有哪些选手、最大对手是谁，评价自己的英文阅读写作能否适应英语科目，以及还报了哪些学校、最想入哪所及原因、与哪个朋友最熟。</p></blockquote><h2 id="record-c1821-hys-2021-second" tabindex="-1">资料来源：【其它机构】升中面试经验汇总_18-21.pdf <a class="header-anchor" href="#record-c1821-hys-2021-second" aria-label="Permalink to &quot;资料来源：【其它机构】升中面试经验汇总_18-21.pdf {#record-c1821-hys-2021-second}&quot;">​</a></h2><p><strong>资料类型：</strong> 不同学生的历史面试反馈汇编</p><p><strong>入学途径：</strong> 中一入学</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="第二轮-·-原文明示" tabindex="-1">第二轮 · 原文明示 <a class="header-anchor" href="#第二轮-·-原文明示" aria-label="Permalink to &quot;第二轮 · 原文明示&quot;">​</a></h3><blockquote><p><strong>考核安排：</strong></p><p><strong>校长会面与陪同差异</strong></p><p>有网上见校长约10至15分钟的反馈；另一家庭由父母陪坐两侧，但父母无须回答，学生先约10分钟英语交谈，再约3至5分钟中文体育问答。</p></blockquote><blockquote><p><strong>英语：</strong> 英语</p><p><strong>介绍引出的职业与经历追问</strong></p><p>从自我介绍、申请资料和奖项展开：想当兽医要怎样实现、应学习哪些科目？讲一次获奖经历，介绍家庭生活、喜欢什么书并推荐一本。也问姊妹的学校生活及感受、为什么报读协恩、还报了什么学校及哪一所具竞争力。</p><p><strong>疫情关怀、朋友与校园建议</strong></p><p>停课时在家做什么？疫情中最关心谁？考生回答长者后，追问如何说服他们戴口罩。若可带一位同学一起入读，会选谁及原因；若分在不同班又怎样？为现就读小学提出一项改善建议，并向校长提一个问题。</p></blockquote><blockquote><p><strong>个人面谈：</strong> 语言未注明</p><p><strong>作家志向与羽毛球经历</strong></p><p>最喜欢和最不喜欢哪科、为何选协恩、怎样实现作家目标？若羽毛球队没有空位会否改选其他活动？羽毛球队经历怎样帮助日后成为作家？另请学生提出协恩小学可改善的地方。</p></blockquote><blockquote><p><strong>体育经历：</strong> 中文（口语未注明）</p><p><strong>专项、成绩与持续投入</strong></p><p>主项和副项是什么、个人最佳成绩多少、会否继续坚持及原因、疫情期间做了什么，以及估计目前可达到什么成绩。</p></blockquote>',21)])])}const u=t(n,[["render",p]]);export{h as __pageData,u as default};
